        if r < 0 || r >= rows || c < 0 || c >= cols { return; }
        if grid[r as usize][c as usize] != '1' { return; }
        grid[r as usize][c as usize] = '0';
        for (dr, dc) in [(1,0),(-1,0),(0,1),(0,-1)] {
            dfs(grid, r + dr, c + dc);
        }
    }

    for r in 0..rows {
        for c in 0..cols {
            if grid[r][c] == '1' { dfs(grid, r as i32, c as i32); count += 1; }
        }
    }
    count
