        let mr1 = if i == m { i32::MAX } else { a[i] };
        let ml2 = if j == 0 { i32::MIN } else { b[j-1] };
        let mr2 = if j == n { i32::MAX } else { b[j] };
        if ml1 <= mr2 && ml2 <= mr1 {
            return if (m + n) % 2 == 0 {
                (ml1.max(ml2) as f64 + mr1.min(mr2) as f64) / 2.0
            } else { ml1.max(ml2) as f64 };
