def rotate(matrix: list[list[int]]) -> list[list[int]]:
    n = len(matrix)

    # anti-diagonal mirror
    for i in range(n):
        for j in range(n - i):
            matrix[i][j], matrix[n-1-j][n-1-i] = matrix[n-1-j][n-1-i], matrix[i][j]

    # horizontal mirror
    for i in range(n // 2):
        for j in range(n):
            matrix[i][j], matrix[n-1-i][j] = matrix[n-1-i][j], matrix[i][j]

    return matrix

