        for (int j = 0; j < n - i; ++j) {
            std::swap(matrix[i][j], matrix[n-1-j][n-1-i]);
        }
    }

    // horizontal mirror
    for (int i = 0; i < n / 2; ++i) {
        for (int j = 0; j < n; ++j) {
            std::swap(matrix[i][j], matrix[n-1-i][j]);
        }
    }

    return matrix;
}

