                if cnts[j] == 0:
                    del cnts[j]

    for i in cnts.keys():
        cnts[i] = 0

    for i in nums:
        if i in cnts:
            cnts[i] += 1

    result = [i for i in cnts.keys() if cnts[i] > n / k]
    return sorted(result)

