        if cnts.len() == k {
            let keys: Vec<i32> = cnts.keys().cloned().collect();
            for j in keys {
                if let Some(val) = cnts.get_mut(&j) {
                    *val -= 1;
                    if *val == 0 {
                        cnts.remove(&j);
                    }
                }
            }
        }
    }

    for val in cnts.values_mut() {
        *val = 0;
    }

    for &i in nums {
        if let Some(val) = cnts.get_mut(&i) {
            *val += 1;
        }
    }

    let mut result: Vec<i32> = cnts
        .into_iter()
        .filter(|&(_, v)| (v as usize) > n / k)
        .map(|(key, _)| key)
        .collect();
    result.sort();
    result
