fn rotate(nums: &mut Vec<i32>, k: i32) -> Vec<i32> {
    fn reverse(nums: &mut [i32], start: usize, end: usize) {
        let mut s = start;
        let mut e = end;
        while s < e {
            nums.swap(s, e - 1);
            s += 1;
            e -= 1;
        }
    }

    let n = nums.len();
    let k = (k as usize) % n;
    reverse(nums, 0, n);
    reverse(nums, 0, k);
    reverse(nums, k, n);
    nums.clone()
}

