std::vector<int> sortColors(std::vector<int>& nums) {
    const int target = 1;
    int right = static_cast<int>(nums.size()) - 1;
    for (int i = 0, left = 0; i <= right;) {
        if (nums[i] > target) {
            std::swap(nums[i], nums[right--]);
        } else {
            if (nums[i] < target) {
                std::swap(nums[left++], nums[i]);
            }
            ++i;
        }
    }
    return nums;
}

